{
  "case_id": "xsu_sg_005_work_capacity_scope",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret konkluderer, at alle syv punkter ikke indgår. Det er forkert for den kommunale arbejdsevnevurdering. Kilden siger, at erhvervsevnevurderingen ikke kan sammenlignes med den, men ikke at den slet ikke indgår som punkt. Svaret er også for absolut om arbejde: kilden siger, at det bl.a. indgår, i hvilket omfang den uddannelsessøgende har eller har haft erhvervsarbejde, og rubrikken nævner tidligere og aktuelt arbejde som støtteelement. De øvrige seks punkter er korrekt udelukket. Den indledende generelle konklusion er dog for ukvalificeret og skaber en juridisk unøjagtighed."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Svaret har målestokken (erhvervsevne under uddannelse) og udelukker punkterne, men det skelner ikke tydeligt mellem vurderingen og den kommunale arbejdsevnevurdering. Det nævner heller ikke funktionsnedsættelsens art og grad eller de ressourcer, personen har. Det siger ikke, at UDK ikke kontakter arbejdsgivere ud over listen, og forklarer ikke, at beskæftigelsessituationen og muligheden for at finde arbejde ikke indgår. Hovedelementerne dækkes delvist, men ikke fuldt."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret behandler hvert af de syv punkter i spørgsmålet direkte og forklarer kort vurderingens fokus."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret nævner ingen identificerbar kilde som lov, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtte mellem påstand og kilde kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret udelukker generelt den kommunale arbejdsevnevurdering og påstår, at vurderingen tager udgangspunkt i begrænsningens betydning for at 'fungere på arbejdsmarkedet'. Det er ikke støttet af kilden, som kun siger, at vurderingen ikke kan sammenlignes med den kommunale. Det er heller ikke støttet, at der kræves 'betydelig reducering', da loven siger 'meget betydelige begrænsninger'."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret bevarer ikke nuancen om, at tidligere og aktuelt erhvervsarbejde kan indgå, og at den kommunale vurdering blot ikke er målestok. Det mister også kravet om 'meget betydelige begrænsninger' ved at skrive 'betydelig reducering'."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Forklaringen om fokus på erhvervsevne under uddannelsen hænger sammen med konklusionen om, at de nævnte punkter ikke indgår. Der er ingen intern modsigelse."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret gør udelukkelsen absolut ('ikke indgår') for den kommunale arbejdsevnevurdering og gengiver ikke kildens mere nuancerede formulering. 'Betydelig reducering' svækker også kravet om 'meget betydelige begrænsninger'."
    }
  },
  "xhaile_coverage": {
    "A15": {
      "label": "partial",
      "reason": "Svaret dækker korrekt, at arbejdsprøvning, særlig arbejdspladsindretning, arbejdsgiverkontakt, studierelevans, lokale forhold/jobmuligheder og erhvervsevne efter uddannelsen ikke indgår, og at målestokken er erhvervsevne under uddannelsen. Det mangler dog 'meget betydelige begrænsninger', eksemplet med ordblindhed, at der gives en vurdering ud fra de ressourcer personen har, og at svært ved at finde arbejde ikke indgår. Det bruger desuden 'betydelig reducering' i stedet for 'meget betydelige'."
    }
  },
  "overall_notes": "Svaret rammer de fleste udelukkelser korrekt, men blander dem sammen med den kommunale arbejdsevnevurdering og undlader, at tidligere og aktuelt arbejde kan indgå. Svaret angiver ingen kilder, hvilket giver C04 not_met og C05/C06 not_assessable."
}

